    def test_a_merge_hook_that_uses_hansa_does_not_hang_the_merge(self):
        tid = self.desk.new_task("Add hello.txt")
        self.assertEqual(self.settle(Dispatcher(self.desk), tid)["state"], "done")
        hansa = str(Path(__file__).resolve().parent.parent / "bin" / "hansa")
        hook = self.repo / ".git" / "hooks" / "post-merge"
        hook.write_text(f'#!/bin/sh\n"{hansa}" --desk "{self.desk.root}" add "queued by a hook" >/dev/null\n')
        hook.chmod(0o755)
        r = subprocess.run([hansa, "--desk", str(self.desk.root), "merge", tid], capture_output=True, text=True, timeout=15)
        self.assertEqual(r.returncode, 0, r.stderr)
        self.assertEqual(self.desk.meta(tid)["state"], "merged")
        self.assertEqual(len(self.desk.tasks()), 1)  # the hook's hansa add was refused at once, not left waiting
        r = subprocess.run([hansa, "--desk", str(self.desk.root), "add", "x"], capture_output=True, text=True, timeout=15,
                           env={**os.environ, "HANSA_MERGING": "1"})
        self.assertNotEqual(r.returncode, 0)
        self.assertIn("hook of a hansa merge", r.stderr)

    def git_out(self, *args, cwd=None) -> str:
        return subprocess.run(["git", *args], cwd=cwd or self.repo, check=True, capture_output=True,
                              text=True).stdout.strip()

    def two_lanes(self, check="", names=("a.txt", "b.txt"), more=None):
        """Lanes a and b on the one repository, each worker writing a file of its own (a.txt, b.txt), and one
        finished task on each, both made from the same base. more: other fields for each lane ({lane: {...}})."""
        s = self.desk.settings()
        s["lanes"]["b"] = json.loads(json.dumps(s["lanes"]["a"]))
        s["lanes"]["a"].update(env={"FAKE_HELLO": names[0]}, check=check)
        s["lanes"]["b"].update(env={"FAKE_HELLO": names[1]}, check=check)
        for lane, fields in (more or {}).items():
            s["lanes"][lane].update(fields)
        self.assertEqual(self.desk.save_settings(s), [])
        d = Dispatcher(self.desk)
        t1, t2 = self.desk.new_task(f"Add {names[0]}", lane="a"), self.desk.new_task(f"Add {names[1]}", lane="b")
        for t in (t1, t2):
            m = self.settle(d, t)
            self.assertEqual((m["state"], (m.get("check") or {"ok": True})["ok"]), ("done", True), m)
        return d, t1, t2

    def settle_merge(self, d, tid, timeout=20):
        end = time.time() + timeout
        while time.time() < end:
            d.tick()
            if self.desk.meta(tid)["state"] != "merging":
                return self.desk.meta(tid)
            time.sleep(0.1)
        self.fail(f"{tid}'s merge check did not end: {self.desk.meta(tid)}")

    def test_two_changes_that_fail_the_check_together_are_not_merged(self):
        d, t1, t2 = self.two_lanes(check="if test -f a.txt && test -f b.txt; then echo a and b clash; exit 1; fi")
        self.assertIn(f"{t1} merged into main", self.hansa("merge", t1))  # the base had not moved: at once
        tip = self.git_out("rev-parse", "main")
        out = self.hansa("merge", t2)
        self.assertIn(f"{t2} is not merged yet: main has 2 commit(s) that {t2}'s branch does not", out)
        self.assertIn(f"hansa wait {t2}", out)
        self.assertEqual(self.desk.meta(t2)["state"], "merging")
        self.assertIn("merge check queued", views.show_text(self.desk, t2))
        self.assertIn(f"{t2} b: Add b.txt\n      merge check queued", views.status_text(views.status(self.desk)))
        m = self.settle_merge(d, t2)
        self.assertEqual((m["state"], m["merge_check_result"]["ok"], m["merge_check_result"]["exit"]), ("done", False, 1))
        self.assertEqual(self.git_out("rev-parse", "main"), tip)  # nothing was merged
        self.assertFalse((self.repo / "b.txt").exists())
        self.assertEqual(Path(self.srt_calls()[-1]["cwd"]).resolve(), (self.desk.worktrees_dir / "b").resolve())
        shown = views.show_text(self.desk, t2)
        self.assertIn(f"ran the lane's check there): FAILED (exit 1)", shown)
        self.assertIn("a and b clash", shown)
        self.assertIn(f"hansa retry {t2} --update", shown)
        self.assertIn("merge check FAILED", views.status_text(views.status(self.desk)))

    def test_two_changes_that_pass_together_merge_after_their_merge_check(self):
        d, t1, t2 = self.two_lanes(check="test -f README.md")
        self.hansa("merge", t1)
        tip = self.git_out("rev-parse", "main")
        self.hansa("merge", t2)
        d.tick()
        self.assertIn("merge check running", views.show_text(self.desk, t2))
        m = self.settle_merge(d, t2)
        self.assertEqual((m["state"], m["merge_check_result"]["ok"]), ("merged", True), m)
        main = self.git_out("rev-parse", "main")
        self.assertEqual(main, m["merge_commit"])
        self.assertEqual(main, m["merge_check_result"]["commit"])  # exactly the commit that was checked
        self.assertEqual(self.git_out("rev-list", "--parents", "-n", "1", main).split()[1:], [tip, m["head"]])
        self.assertTrue((self.repo / "b.txt").exists())
        self.assertEqual(self.git_out("status", "--porcelain"), "")

    def test_a_merge_checks_setup_and_check_write_into_a_pipe_and_their_output_is_kept(self):
        d, t1, t2 = self.two_lanes()
        s = self.desk.settings()
        s["lanes"]["b"].update(setup="echo set up for the merge", check="echo merged badly; exit 3")
        self.assertEqual(self.desk.save_settings(s), [])
        self.hansa("merge", t1)
        calls = len(self.srt_calls())
        self.hansa("merge", t2)
        m = self.settle_merge(d, t2)
        self.assertEqual((m["state"], m["merge_check_result"]["exit"]), ("done", 3), m)
        setup, check = self.srt_calls()[calls:]
        self.assertEqual((self.ran(setup), self.ran(check)),  # the lane's env is set inside the sandbox
                         ("exec /usr/bin/env FAKE_HELLO=b.txt /bin/sh -c 'echo set up for the merge'",
                          "exec /usr/bin/env FAKE_HELLO=b.txt /bin/sh -c 'echo merged badly; exit 3'"))
        self.assertEqual((setup["stdout"], check["stdout"]), ("pipe", "pipe"))
        self.assertIn("set up for the merge", (self.desk.tasks_dir / t2 / "merge-setup.log").read_text())
        self.assertIn("merged badly", (self.desk.tasks_dir / t2 / "merge-check.log").read_text())

    def test_a_merge_check_whose_base_keeps_moving_is_checked_once_more_then_stops(self):
        d, t1, t2 = self.two_lanes()
        s = self.desk.settings()  # a check that moves the base each time it runs
        s["lanes"]["b"]["check"] = f"git -C {self.repo} -c user.name=t -c user.email=t@t commit -q --allow-empty -m moved"
        self.assertEqual(self.desk.save_settings(s), [])
        self.hansa("merge", t1)
        self.hansa("merge", t2)
        m = self.settle_merge(d, t2)
        self.assertEqual((m["state"], m["merge_check_result"]["ok"]), ("done", False), m)
        self.assertIn("moved each time before hansa could merge it; nothing was merged", m["merge_check_result"]["note"])
        self.assertEqual([e["moves"] for e in self.events("merge_check_base_moved")], [1, 2])
        self.assertFalse((self.repo / "b.txt").exists())

    def messages_written(self, forms: dict) -> tuple:
        """Lanes a and b with these message forms (lane: {field: form}); t1 merged at once, t2 retried --update
        onto it as t3, and t3 merged after a merge check. The subjects on main, and (t1, t2, t3, t3's title)."""
        d, t1, t2 = self.two_lanes(check="test -f README.md", more=forms)
        self.hansa("merge", t1)
        self.hansa("retry", t2, "--update", "Add b.txt again")
        t3 = self.desk.meta(t2)["replaced_by"]
        m = self.settle(d, t3)
        self.assertEqual((m["state"], m["update_conflicts"]), ("done", []), m)
        self.move_main()  # so its merge goes through a merge check
        self.hansa("merge", t3)
        m = self.settle_merge(d, t3)
        self.assertEqual((m["state"], m["merge_check_result"]["ok"]), ("merged", True), m)
        self.assertEqual(self.git_out("rev-parse", "main"), m["merge_check_result"]["commit"])
        got = [x.removesuffix("\n") for x in self.git_out("log", "-z", "--format=%B", "main").split("\0") if x]
        return sorted(got), (t1, t2, t3, m["title"])

    def test_unset_message_forms_write_hansas_own_messages(self):
        got, (t1, t2, t3, title) = self.messages_written({})
        self.assertEqual(got, sorted([
            "init", "moved", f"{t1}: Add a.txt", f"Merge {t1}: Add a.txt", f"{t2}: Add b.txt",
            f"Merge main into task/{t3}", f"{t3}: {title}", f"Merge {t3}: {title}"]))

    def test_a_lanes_message_forms_name_every_commit_and_merge_it_writes(self):
        got, (t1, t2, t3, title) = self.messages_written({
            "a": {"commit_message": "{title} [{lane}]", "merge_message": "Merge {task} ({lane}): {title}"},
            "b": {"commit_message": "{title}", "merge_message": "Merge: {title}"}})
        self.assertEqual(title, f"Add b.txt (retry of {t2})")  # a form without {task} leaves that out too
        self.assertEqual(got, sorted([
            "init", "moved", "Add a.txt [a]", f"Merge {t1} (a): Add a.txt", "Add b.txt",
            "Merge main into the branch of: Add b.txt", "Add b.txt", "Merge: Add b.txt"]))
        self.assertNotIn(t2, " ".join(got))
        self.assertNotIn(t3, " ".join(got))
        out = self.hansa("lane")
        self.assertIn('commit_message "{title} [{lane}]"  merge_message "Merge {task} ({lane}): {title}"', out)
        shown = self.hansa("explain", "lane", "b")
        self.assertIn('commit_message (the form of the message of the commit of a task\'s work', shown)
        self.assertIn('merge_message (the form of the message of a task\'s merge into the base): "Merge: {title}"',
                      shown)

    def test_message_forms_that_would_read_badly_are_refused_on_lane_set(self):
        before = self.desk.settings()["lanes"]["a"]
        for field, form, why in (("commit_message", "{title} {when}", "an unknown placeholder {when}"),
                                 ("merge_message", "{title!r}", "an unknown placeholder {title!r}"),
                                 ("merge_message", "Merge {task", "a { or } that opens or closes no placeholder"),
                                 ("commit_message", "{title}\nmore", "must be one line"),
                                 ("commit_message", "   ", "gives an empty message"),
                                 ("merge_message", "Merge {lane}", "gives every task the same message"),
                                 ("merge_message", "{{title}}", "gives every task the same message")):
            with self.assertRaises(SystemExit) as e:
                self.hansa("lane", "set", "a", field, form)
            said = str(e.exception.code)
            self.assertIn(why, said)
            self.assertIn("the placeholders are {task}, {title} and {lane}", said)
            self.assertEqual(len(said.splitlines()), 1, said)
            self.assertEqual(self.desk.settings()["lanes"]["a"], before)
            s = self.desk.settings()  # the page's save is checked the same way
            s["lanes"]["a"][field] = form
            self.assertTrue(any(f"lane a: {field} " in x and why in x for x in self.desk.save_settings(s)))
        self.assertNotIn("_message", self.hansa("lane"))
        self.assertNotIn("_message (the form", self.hansa("explain", "lane", "a"))
        self.assertIn('-> "{task}: {title}"', self.hansa("lane", "set", "a", "commit_message", "{task}: {title}"))
        self.assertIn('commit_message (the form', self.hansa("explain", "lane", "a"))
        self.hansa("lane", "set", "a", "commit_message", "none")  # back to hansa's own
        self.assertNotIn("commit_message", self.desk.settings()["lanes"]["a"])  # taken out, as merge_check is
        self.assertNotIn("_message (the form", self.hansa("explain", "lane", "a"))
        self.assertNotIn("_message", self.hansa("lane"))
        from hansa.desk import merge_message, task_message, update_message
        self.assertEqual(task_message({}, "a", "t0007", ""), "t0007: work")
        self.assertEqual(task_message({"commit_message": "{task}"}, "a", "t0007", "x"), "t0007")
        self.assertEqual(merge_message({"merge_message": "{{{lane}}} {title}"}, "a", "t0007", "x"), "{a} x")
        self.assertEqual(update_message({}, "a", "t0007", "x", "dev"), "Merge dev into task/t0007")
        long = "x" * 75 + " (retry of t0006)"  # cut at 80 by hansa retry
        self.assertEqual(task_message({"commit_message": "{title}"}, "a", "t0007", long[:80]), "x" * 75)
        self.assertEqual(task_message({"commit_message": "{task} {title}"}, "a", "t0007", long[:80]),
                         "t0007 " + long[:80])
        out = io.StringIO()
        with contextlib.redirect_stdout(out), self.assertRaises(SystemExit):
            main(["lane", "set", "--help"])
        self.assertIn("A lane whose release goes to a public repository usually leaves {task} out",
                      " ".join(out.getvalue().split()))

    def identities_written(self, forms: dict, env=None) -> dict:
        """messages_written, then the author and committer of each commit hansa wrote on main, by its message:
        {message: (author, committer)}, each Name <email>."""
        with unittest.mock.patch.dict(os.environ, env or {}):
            self.messages_written(forms)
        rows = self.git_out("log", "-z", "--format=%B%x1f%an <%ae>%x1f%cn <%ce>", "main").split("\0")
        return {x.split("\x1f")[0].strip(): tuple(x.split("\x1f")[1:]) for x in rows
                if x and x.split("\x1f")[0].strip() not in ("init", "moved")}

    def test_a_lanes_identity_is_the_author_and_committer_of_every_commit_and_merge_hansa_writes(self):
        got = self.identities_written({"a": {"identity": "Ada Lane <ada@example.org>"},
                                       "b": {"identity": "  Bo Lane   <bo@example.org> "}})
        self.assertEqual(len(got), 6, got)  # t1, its merge; t2; the update merge, t3, its merge after a merge check
        ada, bo = ("Ada Lane <ada@example.org>",) * 2, ("Bo Lane <bo@example.org>",) * 2
        self.assertEqual({k: v for k, v in got.items() if "Add a.txt" in k}, {k: ada for k in got if "Add a.txt" in k})
        self.assertEqual(sorted(v for k, v in got.items() if "Add a.txt" not in k), [bo] * 4, got)
        self.assertNotIn("hansa", " ".join(a + c for a, c in got.values()))
        shown = self.hansa("explain", "lane", "b")
        self.assertIn("Bo Lane <bo@example.org>, from the lane's identity", shown)
        self.assertIn("design sessions' commits, the commit hansa lane remove --keep makes)", shown)

    def test_without_a_lane_identity_hansa_takes_the_repositorys_own_and_never_the_accounts_global_one(self):
        globl = self.tmp / "global-gitconfig"
        globl.write_text("[user]\n\tname = Global Person\n\temail = global@example.org\n")
        sh("git", "config", "--local", "user.name", "Repo Person", cwd=self.repo)
        sh("git", "config", "--local", "user.email", "repo@example.org", cwd=self.repo)
        got = self.identities_written({}, {"GIT_CONFIG_GLOBAL": str(globl)})
        self.assertEqual(set(got.values()), {("Repo Person <repo@example.org>",) * 2}, got)
        self.assertIn("Repo Person <repo@example.org>, from the repository's own config",
                      self.hansa("explain", "lane", "a"))

    def test_a_repository_identity_git_could_not_write_is_said_to_be_not_usable_and_why(self):
        from hansa.run import lane_identity
        globl = self.tmp / "global-gitconfig"
        globl.write_text("[user]\n\tname = Global Person\n\temail = global@example.org\n")
        sh("git", "config", "--local", "user.name", "Bad <x> Name", cwd=self.repo)
        sh("git", "config", "--local", "user.email", "repo@example.org", cwd=self.repo)
        with unittest.mock.patch.dict(os.environ, {"GIT_CONFIG_GLOBAL": str(globl)}):
            shown = " ".join(self.hansa("explain", "lane", "a").split())
            self.assertIn('hansa <repo@example.org>, from the repository\'s own config (git config --local user.name '
                          'and user.email); hansa\'s own name for what it cannot use (its user.name "Bad <x> Name" is '
                          'not usable: it cannot hold < or >)', shown)
            self.assertNotIn("leaves out", shown)
            sh("git", "config", "--local", "user.email", "re>po@example.org", cwd=self.repo)
            name, email, where = lane_identity(self.desk.settings()["lanes"]["a"])
        self.assertEqual((name, email), ("hansa", "hansa@localhost"))  # never the global one
        self.assertIn("the repository's config sets none that is usable", where)
        self.assertIn('its user.name "Bad <x> Name" is not usable', where)
        self.assertIn('its user.email "re>po@example.org" is not usable: it cannot hold < or >', where)

    def test_hansas_own_name_is_written_only_when_neither_the_lane_nor_the_repository_sets_one(self):
        globl = self.tmp / "global-gitconfig"
        globl.write_text("[user]\n\tname = Global Person\n\temail = global@example.org\n")
        got = self.identities_written({}, {"GIT_CONFIG_GLOBAL": str(globl)})
        self.assertEqual(set(got.values()), {("hansa <hansa@localhost>",) * 2}, got)
        with unittest.mock.patch.dict(os.environ, {"GIT_CONFIG_GLOBAL": str(globl)}):
            shown = self.hansa("explain", "lane", "a")
        self.assertIn("hansa <hansa@localhost>, from hansa's own", shown)
        self.assertIn("should have one: hansa lane set a identity", shown)
        self.assertNotIn("Global Person", shown)

    def test_an_identity_git_could_not_write_is_refused_and_like_copies_one(self):
        before = self.desk.settings()["lanes"]["a"]
        for bad, why in (("Ada Lane", "a name and an email in angle brackets"),
                         ("<ada@example.org>", "needs a name"),
                         ("Ada <>", "needs an email"),
                         ("Ada <ada@example.org", "a name and an email in angle brackets"),
                         ("Ada <x> <ada@example.org>", "cannot hold < or >"),
                         ("Ada > Lane <ada@example.org>", "cannot hold < or >"),
                         ("Ada\nLane <ada@example.org>", "must be one line")):
            for args in (("lane", "set", "a", "identity", bad), ("lane", "add", "c", "--like", "a", "--identity", bad)):
                with self.assertRaises(SystemExit) as e:
                    self.hansa(*args)
                said = str(e.exception.code)
                self.assertTrue(why in said and "Nothing was changed" in said, (bad, said))
                self.assertEqual(len(said.splitlines()), 1, said)
            self.assertEqual(self.desk.settings()["lanes"], {"a": before})
            s = self.desk.settings()  # the page's save is checked the same way
            s["lanes"]["a"]["identity"] = bad
            self.assertTrue(any("lane a: identity " in x and why in x for x in self.desk.save_settings(s)), bad)
        self.assertIn('-> "Ada Lane <ada@example.org>"', self.hansa("lane", "set", "a", "identity", "Ada Lane <ada@example.org>"))
        self.hansa("lane", "add", "c", "--like", "a")
        self.assertEqual(self.desk.settings()["lanes"]["c"]["identity"], "Ada Lane <ada@example.org>")
        self.hansa("lane", "add", "d", "--like", "a", "--identity", "Dee <dee@example.org>")
        self.assertEqual(self.desk.settings()["lanes"]["d"]["identity"], "Dee <dee@example.org>")
        self.hansa("lane", "add", "e", "--like", "a", "--identity", "none")
        self.assertNotIn("identity", self.desk.settings()["lanes"]["e"])
        self.hansa("lane", "add", "f", "--repo", str(self.repo), "--identity", "Eff <f@example.org>")
        self.assertEqual(self.desk.settings()["lanes"]["f"]["identity"], "Eff <f@example.org>")
        self.hansa("lane", "set", "a", "identity", "none")
        self.assertNotIn("identity", self.desk.settings()["lanes"]["a"])
        with contextlib.redirect_stdout(io.StringIO()) as helped, self.assertRaises(SystemExit):
            main(["lane", "set", "--help"])
        said = " ".join(helped.getvalue().split())
        self.assertIn("identity is Name <email>, the author and committer of every commit hansa makes", said)
        self.assertIn("never the account's global one", said)

    def move_main(self, repo=None):
        sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "--allow-empty", "-m", "moved",
           cwd=repo or self.repo)
        return self.git_out("rev-parse", "main", cwd=repo)

    def test_merge_checks_on_one_repository_run_one_after_the_other_in_the_order_asked(self):
        d, t1, t2 = self.two_lanes(check="test -f README.md")
        s = self.desk.settings()
        s["concurrency"] = 2
        self.assertEqual(self.desk.save_settings(s), [])
        tip = self.move_main()  # so both need a merge check
        self.hansa("merge", t1)
        out = self.hansa("merge", t2)
        self.assertIn(f"One merge check runs at a time on main, so it waits for {t1}'s merge check on lane a", out)
        d.tick()
        self.assertEqual(self.desk.meta(t1)["merge_check"]["phase"], "running")
        self.assertEqual(self.desk.meta(t2)["merge_check"]["phase"], "queued")  # lane b is free, but it waits
        waits = f"merge check queued: waits for {t1}'s merge check on lane a"
        self.assertIn(waits, views.show_text(self.desk, t2))
        self.assertIn(waits, views.status_text(views.status(self.desk)))
        self.assertEqual(views.status(self.desk)["merging"][1]["waits_for"], {"id": t1, "lane": "a"})
        self.assertIn(f"waits for {t1}'s merge check on lane a", notify.task_line(self.desk, self.desk.meta(t2)))
        m1 = self.settle_merge(d, t1)
        m2 = self.settle_merge(d, t2)
        self.assertEqual((m1["state"], m2["state"]), ("merged", "merged"), (m1, m2))
        self.assertEqual(m1["merge_check_result"]["onto"], tip)
        self.assertEqual(m2["merge_check_result"]["onto"], m1["merge_commit"])  # checked on the base t1 left
        self.assertEqual(self.git_out("rev-parse", "main"), m2["merge_commit"])
        self.assertEqual(self.events("merge_check_base_moved"), [])  # neither was checked for nothing
        started = [e["task"] for e in self.events("merge_check_started")]
        self.assertEqual(started, [t1, t2])

    def test_a_merge_check_on_another_repository_is_not_held_up(self):
        d, t1, t2 = self.two_lanes(check="test -f README.md")
        other = self.tmp / "other"
        other.mkdir()
        sh("git", "init", "-q", "-b", "main", cwd=other)
        (other / "README.md").write_text("other\n")
        sh("git", "add", ".", cwd=other)
        sh("git", "-c", "user.name=t", "-c", "user.email=t@t", "commit", "-q", "-m", "init", cwd=other)
        s = self.desk.settings()
        s["lanes"]["c"] = {**json.loads(json.dumps(s["lanes"]["a"])), "repo": str(other)}
        s["concurrency"] = 3
        self.assertEqual(self.desk.save_settings(s), [])
        t3 = self.desk.new_task("Add a.txt there", lane="c")
        self.assertEqual(self.settle(d, t3)["state"], "done")
        self.move_main()
        self.move_main(other)
        for t in (t1, t2, t3):
            self.hansa("merge", t)
        d.tick()
        phases = {t: self.desk.meta(t)["merge_check"]["phase"] for t in (t1, t2, t3)}
        self.assertEqual(phases, {t1: "running", t2: "queued", t3: "running"})
        for t in (t1, t2, t3):
            self.assertEqual(self.settle_merge(d, t)["state"], "merged")

    def test_a_merge_needing_no_check_waits_its_turn_behind_a_merge_check(self):
        d, t1, t2 = self.two_lanes(check="sleep 1; test -f README.md")
        s = self.desk.settings()
        s["lanes"]["b"]["check"] = ""  # t2 needs no check
        s["concurrency"] = 2
        self.assertEqual(self.desk.save_settings(s), [])
        self.move_main()  # so t1 needs a merge check
        self.hansa("merge", t1)
        d.tick()
        self.assertEqual(self.desk.meta(t1)["merge_check"]["phase"], "running")
        out = self.hansa("merge", t2)
        self.assertIn(f"{t2} is not merged yet", out)
        self.assertIn(f"so it waits for {t1}'s merge check on lane a", out)
        self.assertIn(f"hansa wait {t2}", out)
        m2 = self.desk.meta(t2)
        self.assertEqual((m2["state"], m2["merge_check"]["phase"], m2["merge_check"]["plain"]), ("merging", "queued", True))
        waits = f"merge queued, to go in without a check if main has still not moved: waits for {t1}'s merge check on lane a"
        self.assertIn(f"{t2} b: Add b.txt\n      {waits}", views.status_text(views.status(self.desk)))
        self.assertIn(waits, views.show_text(self.desk, t2))
        self.assertIn(f"its merge is queued and waits for {t1}'s merge check", notify.task_line(self.desk, m2))
        d.tick()
        self.assertEqual(self.desk.meta(t2)["state"], "merging")  # t1's check still runs
        self.assertFalse((self.repo / "b.txt").exists())
        m1 = self.settle_merge(d, t1)
        m2 = self.settle_merge(d, t2)
        self.assertEqual((m1["state"], m2["state"]), ("merged", "merged"), (m1, m2))
        self.assertEqual(self.git_out("rev-parse", "main"), m2["merge_commit"])
        self.assertEqual(self.git_out("rev-list", "--parents", "-n", "1", "main").split()[1:], [m1["merge_commit"], m2["head"]])
        self.assertEqual(self.events("merge_check_base_moved"), [])  # t1's check was not run again
        self.assertEqual([e["task"] for e in self.events("merge_check_started")], [t1])
        merged = [e for e in self.events("task_merged") if e["task"] == t2]
        self.assertTrue(merged[0]["waited"])
        self.assertIn(f"{t2} merged into main in its turn", notify._item(self.desk, merged[0])[1])

    def test_a_merge_that_waited_its_turn_goes_in_without_a_check_with_its_lanes_merge_message(self):
        d, t1, t2 = self.two_lanes(check="sleep 1; test -f README.md")
        s = self.desk.settings()
        s["lanes"]["b"]["check"] = ""  # t2 needs no check
        s["concurrency"] = 2
        self.assertEqual(self.desk.save_settings(s), [])
        self.hansa("lane", "set", "b", "merge_message", "Merge {task} ({lane}): {title}")
        self.hansa("lane", "set", "b", "identity", "Bo Lane <bo@example.org>")
        self.move_main()  # so t1 needs a merge check
        self.hansa("merge", t1)
        d.tick()
        self.hansa("merge", t2)
        self.assertTrue(self.desk.meta(t2)["merge_check"]["plain"])
        m1 = self.settle_merge(d, t1)
        m2 = self.settle_merge(d, t2)
        self.assertEqual((m1["state"], m2["state"]), ("merged", "merged"), (m1, m2))
        self.assertEqual([e["task"] for e in self.events("merge_check_started")], [t1])  # none ran for t2
        self.assertEqual(self.git_out("log", "-1", "--format=%s", m2["merge_commit"]), f"Merge {t2} (b): Add b.txt")
        self.assertEqual(self.git_out("log", "-1", "--format=%an <%ae>|%cn <%ce>", m2["merge_commit"]),
                         "Bo Lane <bo@example.org>|Bo Lane <bo@example.org>")  # the lane's identity, plain merge too
        self.assertEqual(self.git_out("log", "-1", "--format=%s", m1["merge_commit"]), f"Merge {t1}: Add a.txt")
        self.assertEqual(self.git_out("rev-parse", "main"), m2["merge_commit"])

    def test_a_merge_that_waited_its_turn_and_was_refused_says_no_check_ran(self):
        d, t1, t2 = self.two_lanes(check="sleep 1; test -f README.md")
        s = self.desk.settings()
        s["lanes"]["b"]["check"] = ""  # t2 needs no check, and its lane has none
        s["concurrency"] = 2
        self.assertEqual(self.desk.save_settings(s), [])
        self.move_main()  # so t1 needs a merge check
        self.hansa("merge", t1)
        d.tick()
        self.hansa("merge", t2)
        sh("git", "checkout", "-q", "-b", "elsewhere", cwd=self.repo)  # the principal switched the checkout meanwhile
        self.settle_merge(d, t1)
        m2 = self.settle_merge(d, t2)
        self.assertEqual((m2["state"], m2["merge_check_result"]["waited"]), ("done", True), m2)
        says = "it waited its turn (it needed no check, and none ran), then was not merged: the checkout at"
        shown = views.show_text(self.desk, t2)
        self.assertIn(f"merge: {says}", shown)
        self.assertIn("is on elsewhere, not main", shown)
        self.assertNotIn("ran the lane's check there", shown)
        self.assertNotIn("FAILED", shown)
        self.assertNotIn("it checks the merge again", shown)
        self.assertIn(f"hansa merge {t2} again", shown)
        status = views.status_text(views.status(self.desk))
        self.assertIn(f"merge: {says}", status)
        self.assertNotIn("merge check FAILED", status.split(f"{t2} b:")[1].splitlines()[0])
        ended = [e for e in self.events("merge_check_ended") if e["task"] == t2]
        post = notify._item(self.desk, ended[0])[1]
        self.assertIn(f"{t2}'s merge: {says}", post)
        self.assertIn(f"hansa merge {t2} again", post)

    def test_a_merge_that_waited_is_checked_when_the_base_moved_meanwhile(self):
        d, t1, _ = self.two_lanes(check="sleep 1; test -f README.md")
