    def test_preview_left_by_a_worker_an_earlier_server_started_is_stopped(self):
        self.preview_lane("echo http://localhost:8124; exec sleep 600", FAKE_SEE_TMP=str(self.tmp / "t.jsonl"),
                          FAKE_TMP_WAIT="60")
